.wf-hd-cards {
    --hd-surface: var(--main-background1, var(--wf-color-surface, light-dark(#fff, #101a2b)));
    --hd-raised: var(--main-background2, var(--wf-color-background, light-dark(#f3f6fa, #162235)));
    --hd-text: var(--main-font-color, var(--wf-color-text, light-dark(#15253a, #e5edf8)));
    --hd-muted: var(--main-font-color-light, var(--wf-color-muted, light-dark(#4e6075, #b3c3d7)));
    --hd-line: var(--main-boder-color, var(--wf-color-border, light-dark(#d6dde6, #40516a)));
    --hd-accent: var(--main-button-background, var(--wf-color-primary, light-dark(#167261, #25d9c5)));
    --hd-accent-text: var(--main-button-font-color, var(--wf-color-on-primary, light-dark(#fff, #101a2b)));
    box-sizing: border-box;
    width: min(100%, 1280px);
    padding: 24px clamp(12px, 3vw, 36px) 36px;
    margin-inline: auto;
    color: var(--hd-text);
    font-size: 14px;
}
.wf-hd-cards *, .wf-hd-cards *::before, .wf-hd-cards *::after { box-sizing: border-box; }
.wf-hd-cards [hidden] { display: none !important; }
.wf-hd-cards .wf-hd-overview { display: grid; grid-template-columns: 218px minmax(0, 1fr); gap: 24px; align-items: start; }
.wf-hd-cards .wf-hd-results { min-width: 0; }
.wf-hd-cards .wf-hd-filters { min-width: 0; padding: 14px; background: var(--hd-surface); border: 1px solid var(--hd-line); border-radius: 8px; }
.wf-hd-cards .wf-hd-filters summary { font-weight: 650; cursor: pointer; }
.wf-hd-cards .wf-hd-facets { display: grid; gap: 12px; padding-top: 12px; }
.wf-hd-cards .wf-hd-scope { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 3px; background: var(--hd-raised); border-radius: 6px; }
.wf-hd-cards fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
.wf-hd-cards fieldset + fieldset { border-top: 1px solid var(--hd-line); padding-top: 10px; }
.wf-hd-cards legend { padding: 0; font-size: 12px; font-weight: 650; }
.wf-hd-cards .wf-hd-option { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px; min-height: 34px; font-size: 12px; cursor: pointer; overflow-wrap: anywhere; }
.wf-hd-cards .wf-hd-option input { inline-size: 14px; block-size: 14px; margin: 0; accent-color: var(--hd-accent); }
.wf-hd-cards .wf-hd-option-count { color: var(--hd-muted); font-variant-numeric: tabular-nums; }
.wf-hd-cards .wf-hd-heading { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px 12px; margin-bottom: 12px; }
.wf-hd-cards .wf-hd-title { font-size: 24px; line-height: 1.25; margin: 0; }
.wf-hd-cards :where(.wf-hd-heading button, .wf-hd-scope button, [data-hd-clear], [data-hd-back], [data-hd-cancel], [data-hd-pagination] button, [data-hd-retry]) {
    min-height: 36px; padding: 6px 10px; border: 1px solid var(--hd-line); border-radius: 4px;
    font: inherit; background: var(--hd-surface); color: var(--hd-text);
}
.wf-hd-cards button:not(:disabled) { cursor: pointer; }
.wf-hd-cards :focus-visible { outline: 2px solid var(--hd-accent); outline-offset: 2px; }
.wf-hd-cards [aria-pressed="true"] { border-color: var(--hd-accent); font-weight: 650; }
.wf-hd-cards .wf-hd-primary { color: var(--hd-accent-text); background: var(--hd-accent); border-color: var(--hd-accent); font-weight: 650; }
.wf-hd-cards .wf-hd-feedback { color: var(--hd-muted); margin: 3px 0 0; font-size: 12px; }
.wf-hd-cards .wf-hd-list { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px; margin: 0; padding: 0; list-style: none; }
.wf-hd-cards .wf-hd-list li { min-width: 0; }
.wf-hd-cards .wf-hd-card {
    display: flex; flex-direction: column; align-items: stretch; gap: 5px;
    width: 100%; min-width: 0; padding: 12px 14px;
    text-align: start; font: inherit; color: var(--hd-text); background: var(--hd-surface);
    border: 1px solid var(--hd-line); border-radius: 8px; overflow-wrap: anywhere;
}
.wf-hd-cards .wf-hd-card:hover { border-color: var(--hd-accent); background: var(--hd-raised); }
.wf-hd-cards .wf-hd-card strong { font-size: 16px; line-height: 1.35; font-weight: 650; }
.wf-hd-cards .wf-hd-meta, .wf-hd-cards .wf-hd-number, .wf-hd-cards .wf-hd-date { color: var(--hd-muted); font-size: 12px; }
.wf-hd-cards :where(.wf-hd-number, .wf-hd-date) { font-variant-numeric: tabular-nums; white-space: nowrap; }
.wf-hd-cards .wf-hd-status-row { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; }
.wf-hd-cards .wf-hd-date { margin-inline-start: auto; }
.wf-hd-cards .wf-hd-hour { font-size: 11px; color: color-mix(in srgb, var(--hd-muted) 86%, var(--hd-surface)); }
.wf-hd-cards .wf-hd-description {
    display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;
    overflow: hidden; color: var(--hd-muted); font-size: 13px;
}
.wf-hd-badge {
    display: inline-block; max-width: 100%; padding: 1px 8px; border: 1px solid var(--hd-status-color, var(--hd-line));
    border-radius: 999px; font-size: 12px; font-weight: 600; line-height: 1.5;
    color: color-mix(in srgb, var(--hd-status-color, var(--hd-text)) 36%, var(--hd-text));
    background: color-mix(in srgb, var(--hd-status-color, var(--hd-surface)) 20%, var(--hd-surface));
}
.wf-hd-pagination { display: flex; justify-content: space-between; gap: 8px; margin-top: 12px; }
.wf-hd-cards :where(.wf-hd-detail, .wf-hd-create) { max-width: 840px; margin-inline: auto; min-width: 0; }
.wf-hd-cards :where([data-hd-back], [data-hd-cancel]) { margin-bottom: 12px; }
.wf-hd-cards .elastyc-case-messenger { margin: 0; max-width: none; }
.wf-hd-cards .ecm-header { grid-template-columns: minmax(0, 1fr); }
.wf-hd-cards .ecm-header .wf-hd-meta { order: 0; }
.wf-hd-cards .wf-case-form { margin-inline: 0; }
@media (max-width: 720px) {
    .wf-hd-cards .wf-hd-overview { grid-template-columns: minmax(0, 1fr); gap: 12px; }
    .wf-hd-cards .wf-hd-title { font-size: 20px; }
    .wf-hd-cards .wf-hd-option { min-height: 40px; }
    .wf-hd-cards :where(.wf-hd-heading button, .wf-hd-scope button, [data-hd-back], [data-hd-cancel]) { min-height: 44px; }
}
@media (max-width: 380px) {
    .wf-hd-cards .wf-hd-date { flex-basis: 100%; margin-inline-start: 0; }
}

