(function () {
    'use strict';

    function decode(binding) {
        const bytes = Uint8Array.from(atob(binding.replace(/-/g, '+').replace(/_/g, '/')), value => value.charCodeAt(0));
        return JSON.parse(new TextDecoder().decode(bytes));
    }

    function encode(input) {
        const bytes = new TextEncoder().encode(JSON.stringify(input));
        return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    }

    function text(tag, value, className) {
        const node = document.createElement(tag);
        node.textContent = value;
        if (className) node.className = className;
        return node;
    }

    function statusPill(item, t) {
        const pill = text('span', item.status || (item.closed ? t('Zatvoren', 'Closed') : t('Otvoren', 'Open')), 'wf-hd-badge');
        const color = item['status-color'];
        if (/^#[0-9a-f]{6}$/i.test(color)) pill.style.setProperty('--hd-status-color', color);
        return pill;
    }

    function init(host) {
        const section = host.querySelector('.wf-hd-cards');
        if (!section || section.dataset.hdReady) return;
        section.dataset.hdReady = 'true';
        const english = document.documentElement.lang.toLowerCase().split('-')[0] === 'en';
        const t = (sr, en) => english ? en : sr;
        const typeLabels = new Map([
            ['Greška u radu', 'Something is not working'],
            ['Nova funkcionalnost', 'New feature request']
        ]);
        const typeLabel = value => english ? typeLabels.get(value) || value : value;
        if (english) {
            const copy = {filters: 'Filters', status: 'Status', type: 'Request type', clear: 'Clear filters'};
            section.querySelectorAll('[data-hd-copy]').forEach(element => {
                element.textContent = copy[element.dataset.hdCopy];
            });
            section.querySelector('.wf-hd-filters').setAttribute('aria-label', 'Filters');
        }
        const overview = section.querySelector('[data-hd-overview]');
        const detail = section.querySelector('[data-hd-detail]');
        const create = section.querySelector('[data-hd-create]');
        const createButton = section.querySelector('[data-hd-new]');
        const form = create.querySelector('[data-wf-case-mode]');
        const scopeButtons = Array.from(section.querySelectorAll('[data-hd-scope]'));
        const filters = section.querySelector('[data-hd-filters]');
        const clear = section.querySelector('[data-hd-clear]');
        const groups = Object.fromEntries(Array.from(filters.querySelectorAll('[data-hd-options]'),
            node => [node.dataset.hdOptions, node]));
        const selected = Object.fromEntries(Object.keys(groups).map(key => [key, new Set()]));
        if (window.matchMedia('(max-width: 720px)').matches) filters.open = false;
        const feedback = section.querySelector('[data-hd-feedback]');
        const retry = section.querySelector('[data-hd-retry]');
        const list = section.querySelector('[data-hd-list]');
        const pagination = section.querySelector('[data-hd-pagination]');
        const previous = section.querySelector('[data-hd-previous]');
        const next = section.querySelector('[data-hd-next]');
        const back = section.querySelector('[data-hd-back]');
        const cancel = section.querySelector('[data-hd-cancel]');
        const thread = section.querySelector('[data-hd-thread]');
        const previewBinding = host.dataset.wfProviderPreview;
        const preview = Boolean(previewBinding || host.hasAttribute('data-wf-provider-preview-error') || window.parent !== window);
        const sample = previewBinding ? decode(previewBinding) : null;
        let scope = 'open';
        let page = 1;
        let view = 'list';
        let returnFocus = '';
        let returnScroll = 0;
        let listRequest;
        let threadRequest;
        let completedForm = false;

        async function load(input, signal) {
            const url = new URL(host.dataset.wfProviderUrl, window.location.href);
            url.searchParams.set('wf_input', encode(input));
            const response = await fetch(url, {credentials: 'same-origin', cache: 'no-store', referrerPolicy: 'no-referrer', signal});
            if (!response.ok) throw new Error(String(response.status));
            const result = await response.json();
            if (!result.ok) throw new Error('Provider response');
            return result.data;
        }

        function paintOptions(key, entries) {
            const group = groups[key];
            const focused = group.contains(document.activeElement) ? document.activeElement.value : '';
            const counts = new Map(entries.map(entry => [entry.label, entry.count]));
            for (const value of selected[key]) if (!counts.has(value)) counts.set(value, 0);
            const rows = Array.from(counts, ([label, count]) => {
                const option = text('label', '', 'wf-hd-option');
                const input = document.createElement('input');
                input.type = 'checkbox';
                input.value = label;
                input.checked = selected[key].has(label);
                input.disabled = !input.checked && selected[key].size >= 4;
                option.append(input, text('span', key === 'request-types' ? typeLabel(label) : label), text('span', count, 'wf-hd-option-count'));
                return option;
            });
            if (!rows.length) rows.push(text('p', t('Nema dostupnih opcija', 'No options available'), 'wf-hd-meta'));
            group.replaceChildren(...rows);
            if (focused) {
                Array.from(group.querySelectorAll('input')).find(input => input.value === focused)?.focus();
            }
        }

        function paint(data) {
            for (const key of Object.keys(groups)) paintOptions(key, data[key]);
            clear.hidden = !Object.values(selected).some(values => values.size);
            page = data.page;
            pagination.hidden = page === 1 && !data['has-next'];
            previous.disabled = page === 1;
            next.disabled = !data['has-next'];
            feedback.textContent = data.total
                ? data.total + (data.total === 1 ? t(' predmet', ' request') : t(' predmeta', ' requests'))
                : t('Nema predmeta za izabrane filtere.', 'No requests match these filters.');
            list.replaceChildren(...data.items.map(item => {
                const row = document.createElement('li');
                const card = text('button', '', 'wf-hd-card');
                card.type = 'button';
                card.dataset.hdNumber = item.number;
                const meta = text('span', '', 'wf-hd-status-row');
                meta.append(statusPill(item), text('span', '#' + item.number, 'wf-hd-number'));
                if (item.activity) {
                    const date = item.activity.slice(0, 10).split('-').reverse().join('.') + '.';
                    const time = text('time', date, 'wf-hd-date');
                    time.dateTime = item.activity.replace(' ', 'T');
                    time.title = t('Poslednja vidljiva aktivnost', 'Latest visible activity');
                    time.append(' ', text('span', item.activity.slice(11, 16), 'wf-hd-hour'));
                    meta.append(time);
                }
                card.append(meta, text('strong', item.title));
                if (item.description) card.append(text('span', item.description, 'wf-hd-description'));
                if (item['request-type']) card.append(text('span', typeLabel(item['request-type']), 'wf-hd-meta'));
                card.addEventListener('click', () => navigate('case', item.number));
                row.append(card);
                return row;
            }));
        }

        function previewList() {
            if (!sample) throw new Error('Preview unavailable');
            const rows = sample.items.filter(item => scope === 'all' || !item.closed);
            const matches = (key, value) => !selected[key].size || selected[key].has(value);
            const options = (field, otherKey, otherField) => {
                const counts = new Map();
                for (const item of rows) {
                    const label = item[field];
                    if (label && matches(otherKey, item[otherField])) counts.set(label, (counts.get(label) || 0) + 1);
                }
                return Array.from(counts, ([label, count]) => ({label, count}));
            };
            const items = rows.filter(item => matches('statuses', item.status) && matches('request-types', item['request-type']));
            return {items, total: items.length, page: 1, 'has-next': false,
                statuses: options('status', 'request-types', 'request-type'),
                'request-types': options('request-type', 'statuses', 'status')};
        }

        async function updateList() {
            listRequest?.abort();
            listRequest = new AbortController();
            const {signal} = listRequest;
            retry.hidden = true;
            pagination.hidden = true;
            list.replaceChildren();
            feedback.textContent = t('Učitavanje zahteva…', 'Loading requests…');
            try {
                const input = {scope, page};
                for (const key of Object.keys(groups)) if (selected[key].size) input[key] = [...selected[key]];
                const data = preview ? previewList() : await load(input, signal);
                if (!signal.aborted) paint(data);
            } catch (error) {
                if (signal.aborted) return;
                feedback.textContent = t('Zahtevi trenutno nisu dostupni.', 'Requests are currently unavailable.');
                retry.hidden = false;
            }
        }

        function showView(nextView) {
            threadRequest?.abort();
            if (nextView !== 'case') thread.replaceChildren();
            view = nextView;
            overview.hidden = view !== 'list';
            detail.hidden = view !== 'case';
            create.hidden = view !== 'create';
        }

        function showList() {
            showView('list');
            const card = Array.from(list.querySelectorAll('[data-hd-number]')).find(item => item.dataset.hdNumber === returnFocus);
            const focus = returnFocus === 'new' && !createButton.hidden ? createButton : card || scopeButtons.find(button => button.dataset.hdScope === scope);
            focus.focus({preventScroll: true});
            window.scrollTo(0, returnScroll);
        }

        function rememberList() {
            returnScroll = window.scrollY;
        }

        function navigate(target, number) {
            if (view === 'list') {
                rememberList();
                returnFocus = number || 'new';
                if (window.parent === window) {
                    history.pushState({...history.state, wfHelpDesk: host.dataset.wfInstance, view: target, number}, '');
                }
            }
            if (target === 'case') openCase(number);
            else {
                showView('create');
                if (completedForm) {
                    const mount = form.querySelector('[data-wf-case-mount]');
                    window.ElastycCaseForm?.get(mount)?.restart?.();
                    completedForm = false;
                }
                cancel.focus();
            }
        }

        async function openCase(number) {
            showView('case');
            threadRequest = new AbortController();
            const {signal} = threadRequest;
            back.focus();
            thread.replaceChildren(text('p', t('Učitavanje razgovora…', 'Loading conversation…')));
            try {
                let data;
                if (preview) {
                    const item = sample.items.find(row => row.number === number);
                    data = {thread: {...item, company: 'Primer firme', 'opened-at': item.activity.slice(0, 10), messages: [
                        {id: 1, displayname: 'Podrška', usertype: 'P', datum: '2026-01-12 09:30', text: 'Ovo je primer poruke podrške.'}
                    ]}};
                } else {
                    data = await load({case: number}, signal);
                }
                if (signal.aborted) return;
                const item = data.thread;
                if (!window.ElastycCaseMessenger || !item) throw new Error('Conversation unavailable');
                window.ElastycCaseMessenger.mount(thread, {...item, openedAt: item['opened-at']});
                const status = thread.querySelector('.ecm-status');
                if (status) status.replaceWith(statusPill(item, t));
                if (item['request-type']) thread.querySelector('.ecm-header')?.append(text('p', typeLabel(item['request-type']), 'wf-hd-meta'));
            } catch (error) {
                if (signal.aborted) return;
                thread.replaceChildren(text('p', error.message === '404' ? t('Zahtev više nije dostupan.', 'This request is no longer available.') : t('Razgovor trenutno nije dostupan.', 'The conversation is currently unavailable.')));
            }
        }

        for (const button of scopeButtons) {
            button.addEventListener('click', () => {
                if (scope === button.dataset.hdScope) return;
                scope = button.dataset.hdScope;
                scopeButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
                page = 1;
                updateList();
            });
        }
        for (const [key, group] of Object.entries(groups)) {
            group.addEventListener('change', event => {
                const input = event.target;
                if (input.type !== 'checkbox') return;
                if (input.checked) {
                    if (selected[key].size >= 4) { input.checked = false; return; }
                    selected[key].add(input.value);
                } else {
                    selected[key].delete(input.value);
                }
                page = 1;
                updateList();
            });
        }
        clear.addEventListener('click', () => {
            for (const values of Object.values(selected)) values.clear();
            page = 1;
            scopeButtons.find(button => button.dataset.hdScope === scope).focus();
            updateList();
        });
        previous.addEventListener('click', () => { page--; updateList(); });
        next.addEventListener('click', () => { page++; updateList(); });
        retry.addEventListener('click', updateList);
        createButton.hidden = !form;
        createButton.addEventListener('click', () => navigate('create'));
        form?.addEventListener('elastyc:case-form-success', event => {
            const number = event.detail?.result?.acckey;
            if (preview || !/^[0-9]{2}S[0-9]{8}$/.test(number)) return;
            if (history.state?.wfHelpDesk === host.dataset.wfInstance) {
                history.replaceState({...history.state, view: 'case', number}, '');
            }
            completedForm = true;
            updateList();
            openCase(number);
        });
        function goBack() {
            if (window.parent === window && history.state?.wfHelpDesk === host.dataset.wfInstance) history.back();
            else showList();
        }
        back.addEventListener('click', goBack);
        cancel.addEventListener('click', goBack);
        if (window.parent === window) {
            window.addEventListener('popstate', event => {
                if (event.state?.wfHelpDesk === host.dataset.wfInstance) {
                    if (view === 'list') rememberList();
                    navigateFromHistory(event.state);
                } else if (view !== 'list') showList();
            });
            window.addEventListener('pageshow', event => {
                if (event.persisted) { showView('list'); updateList(); }
            });
        }
        function navigateFromHistory(state) {
            if (state.view === 'case' && state.number) {
                returnFocus = state.number;
                openCase(state.number);
            } else if (state.view === 'create' && form) {
                returnFocus = 'new';
                showView('create');
                cancel.focus();
            }
        }
        if (window.parent === window && history.state?.wfHelpDesk === host.dataset.wfInstance) {
            const {wfHelpDesk, view, number, ...previousState} = history.state;
            history.replaceState(previousState, '');
        }
        if (english && form) {
            const titles = typeLabels;
            form.querySelectorAll('[data-wf-case-fields] [data-options]').forEach(field => {
                const options = field.getAttribute('data-options').split('|').map(option => {
                    const colon = option.indexOf(':');
                    const label = option.slice(colon + 1);
                    return colon < 0 || !titles.has(label) ? option : option.slice(0, colon + 1) + titles.get(label);
                });
                field.setAttribute('data-options', options.join('|'));
            });
            const copy = new Map([
                ['Izaberite', 'Select'],
                ['Izaberite ili pretražite…', 'Select or search…'],
                ['Obavezno polje.', 'This field is required.'],
                ['Izaberite vrednost.', 'Select an option.'],
                ['Opišite korake, očekivani rezultat i šta se dogodilo.', 'Describe the steps, what you expected and what happened.'],
                ['Opišite zahtev i rezultat koji želite da postignete.', 'Describe your request and the outcome you need.']
            ]);
            function translateForm() {
                form.querySelectorAll('select option').forEach(option => {
                    const translated = titles.get(option.textContent) || copy.get(option.textContent);
                    if (translated) option.textContent = translated;
                });
                form.querySelectorAll('[placeholder]').forEach(field => {
                    const translated = copy.get(field.placeholder);
                    if (translated) field.placeholder = translated;
                });
                form.querySelectorAll('[aria-label^="Prikaži opcije: "]').forEach(button => {
                    button.setAttribute('aria-label', button.getAttribute('aria-label').replace('Prikaži opcije:', 'Show options:'));
                });
                form.querySelectorAll('[aria-live], [role="alert"], [id$="-error"]').forEach(message => {
                    const translated = copy.get(message.textContent);
                    if (translated) message.textContent = translated;
                });
            }
            // CaseForm mounts asynchronously and guidance changes when the request type changes.
            const observer = new MutationObserver(translateForm);
            observer.observe(form, { subtree: true, childList: true, characterData: true,
                attributes: true, attributeFilter: ['placeholder'] });
            translateForm();
        }
        updateList();
    }

    document.querySelectorAll('[data-wf-component="help-desk"]').forEach(init);
}());
